/**
 * The typed Management API client used by the postgres link command.
 */
export type ApiClient = ManagementApiClient

/**
 * A project as returned by the Management API.
 */
export type Project = {
  id: string
  name: string
  [key: string]: unknown
}

/**
 * A database as returned by the Management API.
 */
export type Database = {
  id: string
  name: string
  status?: string
  [key: string]: unknown
}

/**
 * Result of creating a dev connection. Contains the connection string that
 * should be written to the local `.env` file as `DATABASE_URL`.
 */
export type ConnectionResult = {
  connectionString: string
}

/**
 * Extracts the error message from a Management API error response body.
 * The API returns errors in the shape `{ error: { code, message, hint } }`.
 */
function apiErrorMessage(error: unknown, fallback: string): string {
  const body = error as { error?: { code?: string; message?: string } } | undefined
  const message = body?.error?.message
  return typeof message === 'string' && message.length > 0 ? message : fallback
}

/**
 * Extracts the error code from a Management API error response body.
 */
function apiErrorCode(error: unknown): string | undefined {
  const body = error as { error?: { code?: string } } | undefined
  return body?.error?.code
}

/**
 * Removes sensitive data from error messages before they are surfaced to the
 * user or logged. Connection strings and API keys must never be leaked.
 */
export function sanitizeErrorMessage(message: string): string {
  return message
    .replace(/(?:prisma\+postgres|postgres):\/\/[^\s'"]+/gi, '[REDACTED_URL]')
    .replace(/--api-key(?:=|\s+)\S+/gi, '--api-key [REDACTED]')
}

/**
 * Creates a new dev connection for the given database and returns the best
 * available connection string. Prefers the direct endpoint, then the pooled
 * endpoint, then the deprecated top-level `connectionString` field.
 */
export async function createDevConnection(client: ApiClient, databaseId: string): Promise<ConnectionResult> {
  let response: Awaited<ReturnType<ApiClient['POST']>>
  try {
    response = await client.POST('/v1/databases/{databaseId}/connections', {
      params: { path: { databaseId } },
      body: { name: 'default' },
    })
  } catch (e) {
    if (e instanceof AuthError) {
      throw new Error('Invalid credentials. Please check your API key and try again.')
    }
    throw e
  }

  const { data, error } = response

  if (error) {
    const code = apiErrorCode(error)
    if (code === 'authentication-failed') {
      throw new Error('Invalid credentials. Please check your API key and try again.')
    }
    if (code === 'not_found') {
      throw new Error(`Database not found: ${databaseId}`)
    }
    throw new Error(sanitizeErrorMessage(apiErrorMessage(error, 'Failed to create connection')))
  }

  const connection = (data as { data?: Record<string, any> } | undefined)?.data

  const connectionString =
    connection?.endpoints?.direct?.connectionString ??
    connection?.endpoints?.pooled?.connectionString ??
    connection?.connectionString

  if (!connectionString) {
    throw new Error('No connection string found in the Management API response')
  }

  return { connectionString }
}

/**
 * Returns the list of projects the authenticated actor has access to.
 */
export async function listProjects(client: ApiClient): Promise<Project[]> {
  const { data, error } = await client.GET('/v1/projects')

  if (error) {
    throw new Error(sanitizeErrorMessage(apiErrorMessage(error, 'Failed to fetch projects')))
  }

  return ((data as { data?: Project[] } | undefined)?.data ?? []) as Project[]
}

/**
 * Returns the list of databases for the given project.
 */
export async function listDatabases(client: ApiClient, projectId: string): Promise<Database[]> {
  const { data, error } = await client.GET('/v1/projects/{projectId}/databases', {
    params: { path: { projectId } },
  })

  if (error) {
    throw new Error(sanitizeErrorMessage(apiErrorMessage(error, 'Failed to fetch databases')))
  }

  return ((data as { data?: Database[] } | undefined)?.data ?? []) as Database[]
}
