import path from 'node:path'

import dotenv from 'dotenv'

import type { ConnectionResult } from './management-api'

/**
 * Metadata describing what happened while writing an environment file.
 */
export type EnvFileResult = {
  created: boolean
  added: string[]
  updated: string[]
}

/**
 * The status of the `.gitignore` file with respect to the `.env` entry.
 */
export type GitignoreStatus = 'no-file' | 'ok' | 'missing-entry'

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Creates or updates a `.env` file with the given key-value pairs.
 *
 * - Creates the file if it does not exist (`created === true`).
 * - Appends keys that are not yet present.
 * - Updates existing keys in-place.
 *
 * Values are always written wrapped in single quotes so that they are treated
 * as literal strings and are not subject to variable expansion. Each line has
 * the exact format `KEY='value'\n`.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): EnvFileResult {
  const exists = fs.existsSync(envPath)
  let content = exists ? fs.readFileSync(envPath, 'utf8') : ''

  const added: string[] = []
  const updated: string[] = []

  for (const [key, value] of Object.entries(vars)) {
    const line = `${key}='${value}'`
    const keyRegex = new RegExp(`^${escapeRegExp(key)}=.*$`, 'm')

    if (keyRegex.test(content)) {
      content = content.replace(keyRegex, line)
      updated.push(key)
    } else {
      if (content.length > 0 && !content.endsWith('\n')) {
        content += '\n'
      }
      content += `${line}\n`
      added.push(key)
    }
  }

  fs.writeFileSync(envPath, content)

  return { created: !exists, added, updated }
}

/**
 * Checks whether a `.gitignore` file exists in the given directory and whether
 * it includes an entry for `.env`.
 */
export function checkGitignore(dir: string): GitignoreStatus {
  const gitignorePath = path.join(dir, '.gitignore')

  if (!fs.existsSync(gitignorePath)) {
    return 'no-file'
  }

  const content = fs.readFileSync(gitignorePath, 'utf8')
  const entries = content.split(/\r?\n/).map((line) => line.trim())

  if (entries.includes('.env') || entries.includes('/.env')) {
    return 'ok'
  }

  return 'missing-entry'
}

/**
 * Writes the `DATABASE_URL` from the given connection to the `.env` file in the
 * specified directory.
 */
export function writeLocalFiles(dir: string, connection: ConnectionResult): { env: EnvFileResult } {
  const envPath = path.join(dir, '.env')
  const env = upsertEnvFile(envPath, { DATABASE_URL: connection.connectionString })
  return { env }
}

/**
 * Returns `true` if the `.env` file in the given directory contains a
 * `DATABASE_URL` that points to a Prisma Postgres host.
 */
export function isAlreadyLinked(dir: string): boolean {
  const envPath = path.join(dir, '.env')

  if (!fs.existsSync(envPath)) {
    return false
  }

  const parsed = dotenv.parse(fs.readFileSync(envPath, 'utf8'))
  const databaseUrl = parsed.DATABASE_URL

  if (!databaseUrl) {
    return false
  }

  return databaseUrl.includes('db.prisma.io') || databaseUrl.includes('db-pool.prisma.io')
}

/**
 * Formats a human-readable summary about the `.env` file operation, including a
 * warning about the `.gitignore` status when appropriate.
 */
export function formatEnvSummary(opts: { env: EnvFileResult; gitignoreStatus: GitignoreStatus }): string {
  const { env, gitignoreStatus } = opts

  let summary = env.created
    ? '  Created .env with connection strings'
    : '  Updated .env with connection strings'

  if (gitignoreStatus === 'missing-entry') {
    summary += '\n    warn Your .gitignore does not include .env — add it to avoid committing secrets'
  } else if (gitignoreStatus === 'no-file') {
    summary += '\n    warn No .gitignore found — create one and add .env to avoid committing secrets'
  }

  return summary
}
