import type { PrismaConfigInternal } from '@prisma/config'
import {
  arg,
  Command,
  createSchemaPathInput,
  format,
  getSchemaWithPathOptional,
  HelpError,
  isError,
} from '@prisma/internals'
import { AuthError } from '@prisma/management-api-sdk'
import { createManagementApiClient } from '@prisma/management-api-sdk'
import { bold, dim, green, red } from 'kleur/colors'

import { login } from '../../management-api/auth'
import { createAuthenticatedManagementAPI } from '../../management-api/auth-client'
import {
  checkGitignore,
  formatEnvSummary,
  isAlreadyLinked,
  writeLocalFiles,
} from './local-setup'
import {
  type ApiClient,
  createDevConnection,
  listDatabases,
  listProjects,
  sanitizeErrorMessage,
} from './management-api'

const DATABASE_ID_PREFIX = 'db_'

/**
 * $ prisma postgres link
 *
 * Links a local project to a Prisma Postgres database by writing the
 * connection string to the local `.env` file.
 */
export class Link implements Command {
  public static new(): Link {
    return new Link()
  }

  private static help = format(`
Link a local project to a Prisma Postgres database

${bold('Usage')}

  ${dim('$')} prisma postgres link [options]

${bold('Options')}

  -h, --help       Display this help message
     --api-key     A Prisma Postgres API key for non-interactive linking
     --database    The ID of the database to link (starts with 'db_')
     --force       Re-link even if the project is already linked
     --schema      Custom path to your Prisma schema

${bold('Examples')}

  Link interactively, selecting a project and database
  ${dim('$')} prisma postgres link

  Link non-interactively with an API key and database ID
  ${dim('$')} prisma postgres link --api-key <key> --database db_xxx
`)

  public async parse(
    argv: string[],
    config: PrismaConfigInternal,
    cwd: string = process.cwd(),
  ): Promise<string | HelpError | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
      '--api-key': String,
      '--database': String,
      '--force': Boolean,
      '--schema': String,
      '--telemetry-information': String,
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args['--help']) {
      return this.help()
    }

    const apiKeyFlag = args['--api-key']
    const databaseFlag = args['--database']
    const force = Boolean(args['--force'])

    // Interactive mode is used when neither an API key nor a database is
    // provided as a flag. Otherwise the command runs non-interactively.
    const isInteractive = !apiKeyFlag && !databaseFlag

    try {
      if (isInteractive) {
        return await this.linkInteractively({ config, cwd, force })
      }

      return await this.linkNonInteractively({ apiKeyFlag, databaseFlag, config, cwd, force })
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      return this.help(sanitizeErrorMessage(message))
    }
  }

  private async linkNonInteractively({
    apiKeyFlag,
    databaseFlag,
    config,
    cwd,
    force,
  }: {
    apiKeyFlag?: string
    databaseFlag?: string
    config: PrismaConfigInternal
    cwd: string
    force: boolean
  }): Promise<string | HelpError> {
    if (!databaseFlag) {
      return this.help(`The --database option is required when linking with --api-key.`)
    }

    if (!databaseFlag.startsWith(DATABASE_ID_PREFIX)) {
      return this.help(
        `The --database value "${databaseFlag}" is invalid. It must be a database ID that starts with '${DATABASE_ID_PREFIX}'.`,
      )
    }

    const token = apiKeyFlag ?? process.env.PRISMA_API_KEY
    if (!token) {
      return this.help(
        `An API key is required. Provide it via --api-key or set the PRISMA_API_KEY environment variable.`,
      )
    }

    if (!force && isAlreadyLinked(cwd)) {
      return this.alreadyLinkedMessage()
    }

    const client = createManagementApiClient({ token })

    let connectionString: string
    try {
      const connection = await createDevConnection(client, databaseFlag)
      connectionString = connection.connectionString
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      return this.help(sanitizeErrorMessage(message))
    }

    return this.writeAndSummarize({ config, cwd, connectionString })
  }

  private async linkInteractively({
    config,
    cwd,
    force,
  }: {
    config: PrismaConfigInternal
    cwd: string
    force: boolean
  }): Promise<string | HelpError> {
    if (!force && isAlreadyLinked(cwd)) {
      return this.alreadyLinkedMessage()
    }

    // Interactive mode always uses browser-based authentication, even if a
    // PRISMA_API_KEY is set in the environment.
    const managementAPI = createAuthenticatedManagementAPI()
    const client = managementAPI.client

    const projects = await this.listProjectsWithReauth(client)

    if (projects.length === 0) {
      return this.help('No projects found. Create a project in the Prisma Console first.')
    }

    const projectId = await select({
      message: 'Select a project:',
      choices: projects.map((project) => ({ name: project.name, value: project.id })),
    })

    const databases = await listDatabases(client, projectId)
    const readyDatabases = databases.filter((database) => database.status === 'ready')

    if (readyDatabases.length === 0) {
      return this.help('No ready databases found for the selected project.')
    }

    let databaseId: string
    if (readyDatabases.length === 1) {
      databaseId = readyDatabases[0].id
    } else {
      databaseId = await select({
        message: 'Select a database:',
        choices: readyDatabases.map((database) => ({ name: database.name, value: database.id })),
      })
    }

    let connectionString: string
    try {
      const connection = await createDevConnection(client, databaseId)
      connectionString = connection.connectionString
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      return this.help(sanitizeErrorMessage(message))
    }

    return this.writeAndSummarize({ config, cwd, connectionString })
  }

  /**
   * Lists projects, retrying once via a browser login if the stored refresh
   * token turns out to be invalid.
   */
  private async listProjectsWithReauth(client: ApiClient) {
    try {
      return await listProjects(client)
    } catch (e) {
      if (!isInvalidRefreshTokenError(e)) {
